'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Feedback, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './feedback.css'
import { CrossGlyph, StarGlyph, TickGlyph } from './glyphs'

/**
 * Feedback: the response to the player's last act.
 *
 * BDS-031 and REQ-045 both land here. Each outcome plays one of the drawing's
 * motions from `packages/tokens/motion.css`: correct pops, wrong shakes, a
 * score increment floats up and fades, a reward slams in. The element that
 * plays it is `data-gs-animates="motion"` and stops dead under reduced motion.
 * The message itself is `data-gs-animates="emphasis"`, because a colour, glyph
 * or text change is how a player who cannot see movement still gets the answer.
 *
 * It performs nothing. It does not decide whether the last act was right, does
 * not know the running score, and does not settle a reward. The host has
 * already decided that by the time it hands this a variant, and this renders
 * it. Rendering is synchronous with the prop on purpose: REQ-045 puts a 100ms
 * ceiling on the gap between a tap and the first visible feedback, and nothing
 * here awaits anything between the prop landing and `[data-gs-feedback]`
 * landing in the DOM.
 */

export type FeedbackVariant = 'correct' | 'wrong' | 'score' | 'reward'

export interface FeedbackProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Which of the four contract values this renders. */
  variant: FeedbackVariant
  /**
   * The text a player reads. Each variant has a default, so a host can render
   * a bare `<Feedback variant="correct" />` and still get an accessible
   * result; supplying a message (the reason an answer was wrong, a reward's
   * name) overrides the default entirely.
   */
  message?: string
  /**
   * The signed amount for a `score` variant's float-up, e.g. `50` or `-10`.
   * Rides `data-gs-delta`, which the attribute contract shares with any
   * element "reporting" a value's change rather than holding the value itself.
   */
  delta?: number
}

/** Fallbacks for a host that renders a variant with no message of its own. */
const DEFAULT_MESSAGE: Record<FeedbackVariant, string> = {
  correct: 'Correct',
  wrong: 'Wrong',
  score: 'Score',
  reward: 'Reward',
}

/** Glyphs, because colour alone is not an answer. Score has none: the number
 *  itself, floating up, is the signal. */
const GLYPH: Partial<Record<FeedbackVariant, React.ReactNode>> = {
  correct: <TickGlyph />,
  wrong: <CrossGlyph />,
  reward: <StarGlyph filled />,
}

/**
 * One capability per outcome, from the drawing's Game Feel sheet (3i): a
 * correct answer pops, a wrong one shakes, a score rises and fades, and a
 * reward celebrates, which is the slam-in. motion.css plays the capability on
 * the element that carries it; the glyph and the label inside stay emphasis,
 * which is the half that survives reduced motion.
 */
const MOTION: Record<FeedbackVariant, 'pop' | 'shake' | 'floatup' | 'celebrate'> = {
  correct: 'pop',
  wrong: 'shake',
  score: 'floatup',
  reward: 'celebrate',
}

function formatDelta(delta: number): string {
  if (delta > 0) return `+${delta}`
  if (delta < 0) return `−${Math.abs(delta)}`
  return `${delta}`
}

export function Feedback({ variant, message, delta, className, ...rest }: FeedbackProps) {
  const label =
    message ?? (variant === 'score' && delta !== undefined ? formatDelta(delta) : DEFAULT_MESSAGE[variant])
  const glyph = GLYPH[variant]

  // One capability per outcome, from the drawing's Game Feel sheet (3i): a
  // correct answer pops, a wrong one shakes, a score rises and fades, and a
  // reward celebrates, which is the slam-in. The part name is the element's
  // job and the capability is what motion.css plays on it; the glyph and the
  // label inside stay emphasis, which is the half that survives reduced motion.
  // The element that moves is the `motion` part, whatever it plays: the part is
  // the job, the attribute is the capability. It used to be named after the
  // capability (`shake`, `float`), which was two words for one element and
  // neither in the part vocabulary.
  const motion = MOTION[variant]

  const content = (
    <>
      {glyph ? (
        <span className="gs-feedback__glyph" data-gs-scope="feedback" data-gs-part="glyph" data-gs-animates="emphasis" aria-hidden="true">
          {glyph}
        </span>
      ) : null}
      {/* The score's number is a display number, so it carries the shared
          display class and the theme's shadow reaches it the way it reaches
          every other number a player reads. The words on a plate are the
          title face, set in feedback.css. */}
      <span
        className={['gs-feedback__label', variant === 'score' ? 'gs-display-type' : null].filter(Boolean).join(' ')}
        data-gs-scope="feedback"
        data-gs-part="label"
        data-gs-animates="emphasis"
        aria-hidden="true"
      >
        {label}
      </span>
    </>
  )

  return (
    <div
      {...rest}
      className={['gs-feedback', className].filter(Boolean).join(' ')}
      data-gs-component="feedback"
      data-gs-feedback={variant}
      data-gs-delta={delta}
      role="status"
      aria-label={label}
    >
      <span
        className="gs-feedback__motion"
        data-gs-scope="feedback" data-gs-part="motion"
        data-gs-motion={motion}
        data-gs-animates="motion"
        aria-hidden="true"
      >
        {content}
      </span>
    </div>
  )
}

/* Feedback. Every value comes from a token; nothing here is a literal colour.

   Specimen 3i draws the three feedback frames, correct, wrong and the points
   floating up, and design/twins/3i.json measures ours against them. Only the
   resting appearance is here: the keyframes at the bottom are the motion
   layer's and are not touched by the pairing. */

.gs-feedback {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-gap);
}

/* -- the plates ------------------------------------------------------------ */
/* Correct, wrong and reward are a word on a plate: the control radius, the
   ui stroke, the title face in capitals where the theme's primary action
   shouts. Correct is filled with positive, ringed in the edge and standing on
   a shelf; wrong is the surface with a dashed negative ring and no shelf, which
   is the frame reduced motion keeps when the shake goes. */
.gs-feedback[data-gs-feedback='correct'],
.gs-feedback[data-gs-feedback='wrong'],
.gs-feedback[data-gs-feedback='reward'] {
  box-sizing: border-box;
  padding: var(--gs-space-3) var(--gs-space-4);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
}

.gs-feedback[data-gs-feedback='correct'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
  box-shadow: 0 var(--gs-press-travel) 0 var(--gs-color-edge);
}

.gs-feedback[data-gs-feedback='wrong'] {
  color: var(--gs-color-negative-solid);
  background: var(--gs-color-surface);
  border-style: dashed;
  border-color: var(--gs-color-negative-solid);
}

.gs-feedback[data-gs-feedback='reward'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  box-shadow: 0 var(--gs-press-travel) 0 var(--gs-color-edge);
}

.gs-feedback__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: 1;
  /* One property borrowed from the action axis, not the axis re-implemented:
     the result word shouts where the theme's primary action shouts. */
  text-transform: var(--gs-type-action-text-transform-primary, var(--gs-type-action-text-transform, none));
  /* Emphasis, not motion: the colour change survives reduced motion, because
     that is how a player who cannot see movement still gets the answer. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* -- the mark -------------------------------------------------------------- */
/* A disc holding the glyph, because colour alone is not an answer. On the
   correct plate the disc is the dark ink and the tick is light; on the wrong
   plate the disc is negative, ringed in the edge, and the cross is light. */
.gs-feedback__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-full);
  font-size: var(--gs-size-icon-utility);
  line-height: 1;
  color: var(--gs-color-ink);
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-feedback[data-gs-feedback='correct'] .gs-feedback__glyph,
.gs-feedback[data-gs-feedback='reward'] .gs-feedback__glyph {
  background: var(--gs-color-on-bright);
}

.gs-feedback[data-gs-feedback='wrong'] .gs-feedback__glyph {
  background: var(--gs-color-negative);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
}

/* -- the points ------------------------------------------------------------ */
/* No plate: the number itself, in positive, standing on the display shadow,
   is the signal. The size is the stat size, the drawing's 26px being between
   the stat and the score tokens. */
.gs-feedback[data-gs-feedback='score'] .gs-feedback__label {
  font-size: var(--gs-type-stat-font-size);
  color: var(--gs-color-positive-solid);
}

/* The element that moves. Which way it moves is data-gs-motion's, applied by
   packages/tokens/motion.css from the drawing's own keyframes: pop, shake,
   floatup or celebrate, one per outcome. Nothing here is timed and no
   keyframe is defined here; this file used to carry its own shake, four full
   swings of 6px, where the drawing damps the last two to 4px, and its own
   float, 24px where the drawing rises 48px.

   Each is an `animation`, not a `transition`: the element mounts once, on
   settlement, with nothing earlier on screen to transition from. Under
   reduced motion, tokens.css forces animation-duration to 0s on anything
   carrying data-gs-animates="motion", so the keyframe still runs, just
   instantly, and its default fill-mode (none) leaves the label sitting at its
   ordinary, fully visible style rather than frozen on a faded-out frame. */
.gs-feedback__motion {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-gap);
}
